package com.interviewiq.service;
import com.interviewiq.api.AuthController;import com.interviewiq.api.AuthDtos.*;import com.interviewiq.domain.AppUser;import com.interviewiq.repository.UserRepository;import com.interviewiq.security.JwtService;import org.springframework.http.HttpStatus;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.web.server.ResponseStatusException;
@Service public class AuthService {private final UserRepository users;private final PasswordEncoder encoder;private final JwtService jwt;public AuthService(UserRepository u,PasswordEncoder e,JwtService j){users=u;encoder=e;jwt=j;}
 public AuthResponse register(Register r){if(users.existsByEmailIgnoreCase(r.email()))throw new ResponseStatusException(HttpStatus.CONFLICT,"An account with this email already exists.");AppUser u=users.save(new AppUser(r.name().trim(),r.email().trim().toLowerCase(),encoder.encode(r.password())));return response(u);}
 public AuthResponse login(Login r){AppUser u=users.findByEmailIgnoreCase(r.email()).filter(x->encoder.matches(r.password(),x.getPasswordHash())).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Email or password is incorrect."));return response(u);}
 public AppUser require(String email){return users.findByEmailIgnoreCase(email).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Profile not found."));}
 @org.springframework.transaction.annotation.Transactional public Profile update(String email,AuthController.ProfileUpdate p){AppUser u=require(email);u.setCollege(p.college());u.setDegree(p.degree());u.setBranch(p.branch());u.setGraduationYear(p.graduationYear());u.setExperienceLevel(p.experienceLevel());u.setTargetRole(p.targetRole());u.setGoal(p.goal());return profile(users.save(u));}
 public Profile profile(AppUser u){return new Profile(u.getId(),u.getName(),u.getEmail(),u.getRole(),u.getCollege(),u.getDegree(),u.getBranch(),u.getGraduationYear(),u.getExperienceLevel(),u.getTargetRole(),u.getGoal());}
 private AuthResponse response(AppUser u){return new AuthResponse(jwt.create(u),u.getRole(),profile(u));}}
